messages.content:
{
  "thought_process": "To restore excellent mobile data speed abroad, I’ll first verify your line’s roaming and data status on our side. In parallel, we’ll optimize a few settings on your phone that commonly block or slow data overseas (roaming settings, network mode, data saver, VPN). Once verified and adjusted, we’ll run a speed test to confirm performance. If your plan’s data is depleted, I can add data (refuel) or discuss plan options.",
  "what_i_need_from_you": {
    "identify_the_line": "Please provide the mobile number for the line that’s in France (e.g., +33 or your home-country number in full international format).",
    "permission": "Do I have your permission to enable international data roaming on your line if it’s currently off? There’s no extra cost just to enable it.",
    "location_context": "Which city in France are you in right now? This helps me consider local network conditions.",
    "availability": "Are you able to follow a few quick steps on your phone now?"
  },
  "quick_device_checks_now": [
    {
      "step": "Turn off Wi‑Fi temporarily",
      "why": "Ensures we’re testing mobile data, not Wi‑Fi.",
      "how": "Open Quick Settings/Control Center and toggle Wi‑Fi off."
    },
    {
      "step": "Confirm Airplane Mode is OFF",
      "why": "Airplane Mode disables cellular and data.",
      "how": "Check the plane icon; if it’s on, turn it off."
    },
    {
      "step": "Enable Data Roaming on the phone",
      "why": "Required for data to work while abroad.",
      "how": "Settings > Cellular/Mobile Data > Cellular Data Options/Mobile Data Options > turn Data Roaming ON."
    },
    {
      "step": "Set Network Mode to 4G/5G preferred",
      "why": "Older modes (2G/3G) are too slow for your ‘excellent’ speed requirement.",
      "how": "Settings > Cellular/Mobile Network > Preferred network type > select 5G/4G (LTE) preferred."
    },
    {
      "step": "Turn Data Saver/Low Data Mode OFF",
      "why": "These modes throttle or block background data and can slow apps.",
      "how": "Settings > Network & Internet/Cellular > Data Saver (Android) or Settings > Cellular > Low Data Mode (iOS) > OFF."
    },
    {
      "step": "Disable any VPN temporarily",
      "why": "VPNs can severely reduce speed, especially when roaming.",
      "how": "Settings > VPN > Disconnect/Off."
    }
  ],
  "next_steps_after_you_reply": [
    "I will look up your line, confirm it’s active, verify/enable roaming, and check your current data usage and plan limits.",
    "If your plan data is used up, I’ll offer to refuel up to 2 GB (priced per GB by your plan) or discuss changing plans.",
    "If needed, we’ll reset APN to defaults and reboot the phone to apply network settings.",
    "We’ll then run a speed test and aim for an ‘excellent’ result. While network conditions vary by area, these steps give you the best chance of top speeds."
  ],
  "please_reply_with": {
    "mobile_number": "Your full mobile number on the affected line",
    "permission_to_enable_roaming": "Yes/No",
    "current_city_in_france": "e.g., Paris, Lyon, Marseille",
    "can_follow_steps_now": "Yes/No and which of the quick checks you’ve already completed"
  }
}

