messages.content:
{
  "acknowledgement": "I can help. We’ll work to restore stable, fast mobile data without Wi‑Fi.",
  "what_im_doing_and_why": "First, I need to identify your line and check for any account/line issues (like data cap, roaming, or suspension). In parallel, we’ll run a few quick checks on your phone to rule out settings that commonly cause slow or no data. This approach lets us fix either an account-side or device-side cause efficiently.",
  "need_from_you": {
    "identify_customer": "Please share the phone number of the line that’s having issues. I’ll use it to look up your account and check plan, usage, roaming, and line status.",
    "traveling_status": "Are you currently traveling outside your usual area or country? (This helps me verify if we need to enable data roaming on your line.)"
  },
  "on_device_checks_now": [
    {
      "step": 1,
      "action": "check_network_status",
      "instructions": "Run the check and tell me: (a) signal strength (none/poor/fair/good/excellent), (b) network type shown (5G/4G/3G/2G), (c) whether Mobile Data is enabled, and (d) whether Data Roaming is enabled."
    },
    {
      "step": 2,
      "action": "run_speed_test",
      "instructions": "Run a speed test over mobile data and share the reported result category (unknown/very poor/poor/fair/good/excellent)."
    },
    {
      "step": 3,
      "action": "check_vpn_status",
      "instructions": "Let me know if a VPN is active/connected."
    },
    {
      "step": 4,
      "action": "check_data_restriction_status",
      "instructions": "Tell me if Data Saver mode is ON and whether background data is restricted globally."
    }
  ],
  "notes": [
    "If Mobile Data is OFF, we’ll turn it ON (toggle_data).",
    "If network mode is stuck on older tech (2G/3G), we’ll switch to 4g_5g_preferred for best speeds.",
    "If Data Saver or a VPN is ON and slowing things, we’ll turn them OFF.",
    "If you’re roaming and data roaming is OFF or your line isn’t roaming-enabled, I can enable roaming on your line at no cost.",
    "If your plan’s monthly data limit has been reached, we can refuel up to 2 GB immediately or discuss plan changes."
  ],
  "next_steps": "Please provide your phone number and the results from steps 1–4. I’ll check your line on my side as soon as I have the number and guide you through the exact fixes based on what we find."
}

