    },
    "implication": "Your line is active, roaming is enabled on our side, and you have data left. The issue is likely device settings while roaming or local network selection. We’ll optimize your phone settings."
  },
  "thought_process": "Since you’re abroad and roaming is enabled on the account, intermittent or slow data is often caused by the phone’s roaming/data settings, network mode preference (falling back to 2G/3G), Data Saver, or an active VPN. We’ll quickly verify and correct those, then measure speed.",
  "do_this_next_on_your_phone": [
    {
      "step": 1,
      "title": "Confirm phone-side data roaming and basic connectivity",
      "action": "check_network_status",
      "what_to_report_back": [
        "Airplane Mode ON/OFF",
        "Signal strength (none/poor/fair/good/excellent)",
        "Network type shown (5G/4G/3G/2G)",
        "Mobile Data Enabled (yes/no)",
        "Data Roaming Enabled (yes/no)"
      ],
      "if_roaming_is_off": {
        "action": "toggle_roaming",
        "set_to": "ON",
        "note": "Roaming must be ON on the phone when abroad."
      }
    },
    {
      "step": 2,
      "title": "Make sure you’re not accidentally in Airplane Mode and that data is on",
      "action": "check_status_bar",
      "look_for": [
        "No airplane icon",
        "A 4G or 5G icon if available",
        "Data icon present"
      ],
      "quick_fixes_if_needed": [
        { "action": "toggle_airplane_mode", "how": "Turn ON, wait 10 seconds, then turn OFF" },
        { "action": "toggle_data", "how": "Turn mobile data OFF, wait 10 seconds, then turn it back ON" }
      ]
    },
    {
      "step": 3,
      "title": "Prefer faster networks",
      "action": "check_network_mode_preference",
      "if_you_see": ["2G", "3G", "3G/2G preferred"],
      "do_this": {
        "action": "set_network_mode_preference",
        "mode": "4g_5g_preferred"
      },
      "note": "This helps avoid slow legacy networks."
    },
    {
      "step": 4,
      "title": "Disable Data Saver (if on)",
      "action": "check_data_restriction_status",
      "if_data_saver_is_on": {
        "action": "toggle_data_saver_mode",
        "set_to": "OFF"
      }
    },
    {
      "step": 5,
      "title": "Ensure no VPN is slowing data",
      "action": "check_vpn_status",
      "if_vpn_is_connected": {
        "action": "disconnect_vpn"
      }
    },
    {
      "step": 6,
      "title": "Test the connection quality (cellular only)",
      "prep": "Keep Wi‑Fi off so we test mobile data only.",
      "action": "run_speed_test",
      "what_to_report_back": [
        "Speed test rating (very poor/poor/fair/good/excellent) or numbers if shown"
      ]
    },
    {
      "step": 7,
      "title": "If pages still stall intermittently",
      "try_in_order": [
        { "action": "toggle_data", "how": "OFF then ON" },
        { "action": "toggle_airplane_mode", "how": "ON for 10 seconds, then OFF" },
        { "action": "reboot_device", "how": "Full restart of the phone" }
      ]
    },
    {
      "step": 8,
      "title": "If MMS/web still behave oddly, reset APN",
      "diagnose": { "action": "check_apn_settings", "what_to_check": "APN name and MMSC URL present" },
      "if_incorrect_or_missing": [
        { "action": "reset_apn_settings" },
        { "action": "reboot_device" }
      ]
    }
  ],
  "please_reply_with": [
    "Results of Step 1 (all items listed, especially Data Roaming and network type).",
    "What your status bar shows for signal bars and 5G/4G/3G/2G.",
    "Your network mode preference result and any change you made in Step 3.",
    "Whether Data Saver or a VPN was ON and what you changed.",
    "The speed test rating from Step 6.",
    "Whether the intermittent drop still happens after Step 7."
  ],
  "optional_info": {
    "location_specificity": "If the issue is much worse indoors or in specific neighborhoods, tell me where it happens most. That helps pinpoint local coverage versus settings.",
    "data_refuel_option": "You still have 6.3 GB left this cycle. If you expect to need more, I can add up to 2 GB immediately at $2/GB—just tell me how many GB (0.5–2.0 in 0.5 steps)."
  },
  "next_after_your_update": "I’ll review your results, make any carrier-side changes still needed, and fine-tune settings (e.g., keep 4G/5G preferred or adjust) to get you to excellent speeds."
}

