messages.content:
{
  "message": "Great work confirming mobile data is ON and fast. Since MMS still won’t send, the most common next causes are APN/MMSC configuration, Wi‑Fi Calling interactions, or the messaging app lacking permissions. We’ll check and fix those in order.",
  "thought_process": "MMS requires: active service (OK), mobile data ON (now OK), suitable network (5G OK), correct APN with a valid MMSC URL, no conflicting Wi‑Fi Calling state, and the messaging app having Storage and SMS permissions. We’ll verify each and apply fixes.",
  "steps": [
    {
      "title": "Quick MMS diagnostic",
      "do_on_phone": "Run can_send_mms and tell me the result (pass/fail or any error shown).",
      "why": "Confirms whether the messaging stack sees a configuration problem."
    },
    {
      "title": "Check APN and MMSC",
      "do_on_phone": "Run check_apn_settings and look for an MMSC URL. If the MMSC URL is missing/blank or looks incorrect, run reset_apn_settings and then reboot_device to apply the defaults.",
      "after_reboot": "Test sending an MMS again (a picture to your own number is fine).",
      "why": "A missing/incorrect MMSC is the most frequent cause of MMS failures."
    },
    {
      "title": "Rule out Wi‑Fi and Wi‑Fi Calling effects",
      "do_on_phone": [
        "Run check_wifi_calling_status. If Wi‑Fi Calling is ON, use toggle_wifi_calling to turn it OFF.",
        "Temporarily turn Wi‑Fi OFF using toggle_wifi, then try sending an MMS again."
      ],
      "why": "Some configurations interfere with MMS. Testing with Wi‑Fi and Wi‑Fi Calling OFF isolates the mobile-data MMS path."
    },
    {
      "title": "Confirm messaging app permissions",
      "do_on_phone": [
        "Run check_app_permissions for your messaging app (use app_name=\"messaging\").",
        "If \"storage\" and/or \"sms\" are not granted, run grant_app_permission for permission=\"storage\" and permission=\"sms\"."
      ],
      "then_test": "Try sending an MMS again.",
      "why": "Without Storage or SMS permission, the app may fail to send MMS."
    },
    {
      "title": "Disable data restrictions (if active)",
      "do_on_phone": "Run check_data_restriction_status. If Data Saver mode is ON, run toggle_data_saver_mode to turn it OFF.",
      "then_test": "Send an MMS again.",
      "why": "Data Saver can impede background data needed for MMS."
    },
    {
      "title": "If you use a VPN, disconnect it",
      "do_on_phone": "Run check_vpn_status. If a VPN is connected, run disconnect_vpn and test MMS again.",
      "why": "Some VPN configurations can break MMS traffic."
    }
  ],
  "please_report_back": [
    "Result of can_send_mms.",
    "From check_apn_settings: is there an MMSC URL present? If you reset APN, confirm you ran reboot_device and whether MMS worked afterward.",
    "Whether Wi‑Fi Calling was ON and if turning it OFF helped; also if turning Wi‑Fi OFF changed anything.",
    "Whether messaging app permissions (storage and sms) were granted or needed to be granted.",
    "Whether Data Saver or a VPN was ON and if turning them OFF helped."
  ],
  "next_steps": "If MMS still fails after the APN reset + reboot and the other checks, we’ll take a closer look at any error from can_send_mms and consider additional device refresh steps."
}

