      "title": "Confirm messaging app permissions",
      "do_on_phone": [
        "Check messaging app permissions (check_app_permissions with app_name=\"messaging\").",
        "If \"storage\" and/or \"sms\" are not granted, grant them (grant_app_permission for \"storage\" and \"sms\")."
