messages.content:
{
  "assessment": "Your phone reports 'No SIM card detected' (SIM status: Missing). When a SIM is not detected, the device cannot register on the network, which explains No Signal and disabled data. The fastest, policy-aligned fix is to reseat the SIM.",
  "reasoning": "A missing SIM indicates a physical seating/reader detection issue rather than an account problem. Reseating often restores detection. If not, cross‑testing isolates whether the fault is the SIM card or the phone’s SIM reader.",
  "action_now_reseat_sim": [
    "Power the phone OFF completely.",
    "Eject the SIM tray. Verify the SIM is oriented correctly (notched corner alignment) and sits flat in the tray.",
    "Gently wipe the SIM’s gold contacts with a dry, lint‑free cloth. Do not use liquids.",
    "Inspect the tray for debris/bends; remove any visible dust carefully.",
    "Reinsert the SIM tray fully and flush.",
    "Power the phone ON and wait 1–2 minutes.",
    "Check the status bar and SIM status again (Settings > Network & Internet > SIM/Cellular)."
  ],
  "if_then_next_steps": [
    {
      "condition": "SIM status becomes Active and signal bars appear",
      "do": [
        "Confirm you can place a call or load a webpage on mobile data."
      ]
    },
    {
      "condition": "SIM status becomes Locked",
      "do": [
        "Do not attempt random PIN/PUK entries.",
        "Tell me it shows Locked so I can transfer you to a human agent for secure unlock assistance."
      ]
    },
    {
      "condition": "SIM status still shows Missing after reseat",
      "do": [
        "Cross‑test to isolate the issue:",
        "- If available, insert your SIM into another compatible phone.",
        "- Or insert a known‑good SIM into your phone.",
        "Report which combination worked. This tells us whether the SIM card is faulty (works in other phone = phone reader issue; doesn’t work anywhere = SIM issue)."
      ]
    }
  ],
  "what_i_will_do_next": "Based on your results: (a) if Active but still no service, I will guide you through the next network steps; (b) if Locked, I will transfer you to a human agent for PIN/PUK; (c) if Missing persists and cross‑test points to a bad SIM or SIM reader, I will proceed accordingly (SIM replacement or escalation).",
  "please_reply_with": [
    "After reseating: SIM status (Active/Missing/Locked) and whether any signal bars/network label appear.",
    "If still Missing: the outcome of the cross‑test (your SIM in another phone, or another SIM in your phone)."
  ]
}

