messages.content:
{
  "thought_process": "Great—moving from 2G to 5G ruled out the most common MMS blocker. With strong signal and mobile data ON, next we should eliminate feature conflicts (Wi‑Fi Calling, Data Saver, VPN), then verify the MMSC in your APN. An incorrect/missing MMSC is a frequent cause of MMS stuck on “sending.”",
  "do_this_next_in_order": [
    {
      "step": "Turn OFF Wi‑Fi Calling (if ON)",
      "why": "Wi‑Fi Calling can interfere with MMS on some configurations.",
      "android_how": "Settings > Network & Internet (or Connections) > Wi‑Fi Calling > turn OFF",
      "test_after": "With Wi‑Fi still OFF and Mobile Data ON, try sending an MMS."
    },
    {
      "step": "Make sure Data Saver is OFF and no VPN is active",
      "why": "Data Saver can restrict background data; VPNs can disrupt MMS routing.",
      "android_how": [
        "Data Saver: Settings > Network & Internet > Data Saver > turn OFF",
        "VPN: Settings > Network & Internet > VPN > if Connected, Disconnect"
      ],
      "test_after": "Try sending an MMS again."
    },
    {
      "step": "Verify APN/MMSC; reset APN to default if unsure",
      "why": "MMS requires a valid MMSC server in the APN. If missing/incorrect, MMS won’t send.",
      "android_how": [
        "Go to Settings > Mobile network (or SIMs) > Access Point Names.",
        "Tap the active APN. Confirm there is an MMSC entry and it’s populated.",
        "If MMSC is missing/looks wrong or if you’re unsure: use the 3‑dot menu > Reset to default."
      ],
      "important": "After resetting APN, REBOOT the phone to apply changes.",
      "test_after": "Once rebooted, keep Wi‑Fi OFF, ensure Mobile Data ON, and try sending an MMS."
    },
    {
      "step": "Check Messaging app permissions (if still failing after APN reset + reboot)",
      "why": "The app needs Storage/Photos and SMS permissions to handle media and send MMS.",
      "android_how": [
        "Settings > Apps > [Your messaging app] > Permissions",
        "Allow: Files and media (or Photos/Media/Storage) and SMS (or Send/Receive SMS)."
      ],
      "test_after": "Try sending an MMS again."
    },
    {
      "step": "Optional quick data check",
      "why": "Confirms mobile data is actually passing traffic.",
      "android_how": "With Wi‑Fi OFF, open a browser and load a couple of websites or run a speed test app."
    }
  ],
  "what_to_report_back": [
    "Was Wi‑Fi Calling ON? If so, did turning it OFF change anything?",
    "Was Data Saver ON or a VPN connected?",
    "In APN > active APN, was there an MMSC value? Did you reset APN and then reboot?",
    "After the reboot, with Wi‑Fi OFF and Mobile Data ON, does MMS send or still spin?",
    "Did the messaging app have Storage/Files & SMS permissions allowed?"
  ],
  "notes": [
    "Keep Wi‑Fi OFF during each MMS test so we’re using mobile data.",
    "You’re on 5G with excellent signal, so if an APN reset + reboot fixes the MMSC, MMS should start working."
  ]
}

