    {
      "title": "Turn Wi‑Fi OFF temporarily",
      "why": "Ensures we test true mobile data, which MMS needs.",
      "what_to_do": "Swipe down and turn off Wi‑Fi."
    },
    {
      "title": "Ensure Mobile data is ON",
      "why": "MMS won’t send without mobile data.",
      "what_to_do": "Settings > Network & Internet (or Connections) > SIMs/Mobile network > turn Mobile data ON."
    },
    {
      "title": "Enable Data Roaming on the phone",
      "why": "You’re in France; data roaming must be ON on the device even though your line is roaming-enabled on our side.",
      "what_to_do": "Settings > Network & Internet > SIMs/Mobile network > Roaming > turn Data roaming ON."
    },
    {
      "title": "Quick data test",
      "why": "Verifies that mobile data actually works.",
      "what_to_do": "With Wi‑Fi OFF, open a browser and try loading example.com. Tell me if it loads."
    },
    {
      "title": "Test MMS",
      "why": "Checks if enabling data/roaming resolved it.",
      "what_to_do": "Send a picture message to a contact and report what happens."
    },
    {
      "title": "If still failing: turn OFF Wi‑Fi Calling",
      "why": "Some configurations block MMS over Wi‑Fi/when Wi‑Fi Calling is active.",
      "what_to_do": "Settings > Network & Internet (or Calls & SMS) > Wi‑Fi Calling > turn OFF, then retry MMS."
    },
    {
      "title": "If still failing: disable Data Saver and any VPN",
      "why": "Both can interfere with MMS/data flow.",
      "what_to_do": "Settings > Network & Internet > Data Saver > OFF. Then Settings > VPN > disconnect any VPN. Retry MMS."
    },
    {
      "title": "Ensure preferred network is 4G/5G",
      "why": "2G/3G can break MMS.",
      "what_to_do": "Settings > Mobile network > Preferred network type > select 4G/5G (or LTE/5G). Retry MMS."
    },
    {
      "title": "Check APN/MMSC, reset if unsure",
      "why": "A missing/incorrect MMSC prevents MMS.",
      "what_to_do": "Settings > Mobile network > Access Point Names. Ensure an APN is selected and that its MMSC field is present. If blank/unsure: tap menu > Reset to default. Then reboot the phone and test MMS again."
    }
  ],
  "what_i_need_from_you_now": "Yes, please start with Steps 1–6: share the status bar details, confirm Mobile data and Data roaming are ON, tell me whether example.com loads with Wi‑Fi OFF, and whether the MMS sends. Based on that, I’ll guide you to the next specific fix if needed."
}

