messages.content:
{
  "empathy": "I understand why you’re worried—thanks for hanging in there. The good news is your data connection is fine on 5G, so we’re likely down to settings that commonly block MMS. The most effective next step is to refresh the APN/MMSC settings, then check the Messages app permissions.",
  "thought_process": "MMS depends on a correct MMSC value in your APN. If that’s wrong or stale, MMS fails even when internet works. Resetting APN restores the correct defaults. If that doesn’t do it, we verify the Messages app has storage/SMS permissions and that Data Saver isn’t restricting it.",
  "step_1_apn_reset_then_reboot": {
    "title": "Reset APN to default (fixes MMSC), then restart",
    "why": "An incorrect or missing MMSC in APN is a very common cause of MMS failures.",
    "android_instructions": [
      "Open Settings.",
      "Go to Network & Internet (or Connections) > Mobile network.",
      "Tap Access Point Names (APN).",
      "Tap the menu (⋮) in the top-right and select Reset to default.",
      "After it resets, power the phone OFF, wait 10 seconds, then power it ON.",
      "Keep Wi‑Fi OFF and Mobile Data ON, then try sending a picture message again."
    ],
    "reassurance": "This won’t erase any data or photos. It only restores your carrier’s network settings."
  },
  "step_2_app_permissions": {
    "title": "If Step 1 doesn’t fix it: check Messages app permissions",
    "why": "The app needs Storage/Photos and SMS permissions to attach and send media.",
    "android_instructions": [
      "Settings > Apps > Messages (or your default messaging app).",
      "Permissions > Allow SMS (if listed) and Files and media/Storage (or Photos and videos).",
      "Also check: Mobile data & Wi‑Fi (or Data usage) > Allow background data."
    ]
  },
  "step_3_data_saver": {
    "title": "If still not working: turn OFF Data Saver and allow unrestricted data for Messages",
    "why": "Data Saver can restrict background data and break MMS sending.",
    "android_instructions": [
      "Settings > Network & Internet (or Connections) > Data Saver > turn OFF.",
      "Settings > Apps > Messages > Mobile data & Wi‑Fi (or Data usage) > turn ON Unrestricted data (if available)."
    ]
  },
  "step_4_vpn_check": {
    "title": "If you use a VPN, disconnect it and retry",
    "why": "Some VPNs interfere with MMS routing.",
    "android_instructions": [
      "Open your VPN app and disconnect, or",
      "Settings > Network & Internet > VPN > Disconnect."
    ]
  },
  "step_5_network_mode_verify": {
    "title": "Verify Preferred Network Type",
    "why": "MMS needs at least 3G; 4G/5G preferred. You show 5G already, but let’s confirm the setting isn’t constrained.",
    "android_instructions": [
      "Settings > Network & Internet (or Connections) > Mobile network > Preferred network type.",
      "Select 5G/4G (LTE) preferred (or 4G only)."
    ]
  },
  "request": "Please start with Step 1 (APN reset + restart), then try sending a picture again. If it still says “Not sent,” we’ll immediately do Step 2 (permissions).",
  "questions": [
    "Were you able to find Access Point Names and reset to default?",
    "After the restart, did the picture message send?",
    "If not, shall we check the Messages app permissions together next?"
  ],
  "reassurance": "You’re very close. These steps are safe and commonly resolve exactly this symptom. I’ll stay with you through each step—tell me what you see and I’ll adjust as needed."
}

