      "how_iphone": "Settings > Cellular > Cellular Data Options > Voice & Data > select 5G On/Auto or LTE."
    },
    {
      "title": "Check Data Saver and VPN",
      "why": "Data Saver can restrict data; VPNs can break MMS/data paths.",
      "do_android": [
        "Settings > Network & Internet > Data Saver > turn OFF.",
        "If you use a VPN: Settings > Network & Internet > VPN > Disconnect."
      ],
      "do_iphone": [
        "Settings > Cellular > Cellular Data Options > Low Data Mode OFF.",
        "If you use a VPN: Settings > VPN > turn OFF."
      ]
    },
