messages.content:
{
  "explanation": "Not normal, but clear: your phone reports “SIM missing,” which explains the “no service,” no signal bars, and data being disabled. Without a detected SIM, the phone can’t register on any network, so MMS (and mobile data) won’t work. The most common cause is a SIM that’s not seated correctly or has poor contact. I already enabled international roaming on your line earlier, so once the SIM is detected, we can turn on data/roaming on the phone and MMS should work.",
  "why_this_happens": "If the SIM isn’t detected, the network can’t authenticate your line. This shows as “No Service/SIM missing,” even if airplane mode is off.",
  "next_steps_now": {
    "goal": "Get the SIM recognized by the phone.",
    "instructions": [
      "Power the phone OFF completely.",
      "Remove the SIM tray gently. Note the SIM’s orientation (notch/cut corner).",
      "Wipe the gold contacts on the SIM lightly with a clean, dry cloth (no liquids).",
      "Reinsert the SIM flat and fully, correct orientation, and push the tray in flush.",
      "Power the phone ON and wait 1–2 minutes."
    ],
    "then_check": [
      "Does the status bar now show your carrier name and signal bars (e.g., 4G/LTE/5G)?",
      "Does SIM status change from “Missing” to “Active” (or similar)?"
    ]
  },
  "if_sim_is_now_detected": {
    "enable_on_phone": [
      "Turn Mobile Data ON.",
      "Turn Data Roaming ON (since you’re in France)."
    ],
    "how_to_enable": [
      "iPhone: Settings > Cellular (Mobile Data) > turn Cellular Data ON; then Cellular Data Options > Data Roaming ON.",
      "Android: Settings > Network & Internet (or Connections) > Mobile network (or SIMs) > turn Mobile data ON and Roaming ON."
    ],
    "verify_connection": [
      "With Wi‑Fi OFF, open a website (e.g., example.com). If it loads, data works.",
      "Try sending an MMS again (while Wi‑Fi is still OFF)."
    ],
    "if_mms_still_fails": [
      "Temporarily turn Wi‑Fi Calling OFF (if enabled) and retry MMS.",
      "Reset APN to default (Android: Settings > Mobile network > Access Point Names > menu > Reset to default; iPhone: if APN fields visible, use Reset at bottom of Cellular Data Network), then RESTART the phone and retry MMS."
    ]
  },
  "if_sim_is_still_missing": {
    "try_these": [
      "Repeat the reseat once more carefully.",
      "If possible, test your SIM in another phone, or test another known‑working SIM in your phone. This isolates whether it’s the SIM or the phone."
    ],
    "outcomes": [
      "If your SIM works in another phone but not in yours: likely a phone SIM reader issue.",
      "If your SIM does not work in another phone: likely a faulty/damaged SIM."
    ],
    "next_action": "Tell me what you find. If the SIM remains Missing or becomes Locked (PIN/PUK), do not try random codes. I will transfer you to a human agent for SIM replacement or security unlock assistance."
  },
  "reassurance": "Your phone itself is probably okay; this is most often a seating/contact issue with the SIM. Once the SIM is detected, we’ll finish by enabling mobile data/roaming and testing MMS.",
  "please_confirm": [
    "After the reseat and restart, what does the SIM status show now (Active/Missing/Locked)?",
    "Do you see signal bars and a network type (4G/LTE/5G)?",
    "If detected, were you able to load a webpage with Wi‑Fi OFF and send an MMS?"
  ]
}

