messages.content:
{
  "summary": "I can help troubleshoot 'No Service' and check whether your line is suspended or otherwise impacted. We’ll do two things in parallel: verify your account/line status on our side, and run a few quick checks on your phone to rule out common causes like Airplane Mode or a SIM issue.",
  "why_these_steps": [
    "No Service is most commonly caused by Airplane Mode being ON, a SIM issue (mis-seated or locked), incorrect network settings, or an account/line suspension.",
    "Checking your account ensures there’s no suspension or billing hold. The device checks quickly rule out phone-side causes."
  ],
  "what_I_need_from_you": {
    "to_identify_your_account": "Please provide ONE of the following so I can look up your line:",
    "options": [
      "Phone number for the affected line",
      "Customer ID",
      "Full name AND date of birth (YYYY-MM-DD)"
    ],
    "device_details": [
      "Phone make/model (e.g., iPhone 13, Samsung S21)",
      "Are you currently traveling outside your usual area or abroad?",
      "Did this start suddenly today, and did anything change just before it (update, SIM/eSIM change, new phone)?"
    ]
  },
  "quick_device_checks_now": [
    {
      "step": "Check Airplane Mode",
      "how": "Open Quick Settings/Control Center and ensure Airplane Mode is OFF. If it’s ON, turn it OFF. If already OFF, toggle it ON for 10 seconds and then OFF.",
      "reason": "Airplane Mode disables all cellular radios and causes No Service."
    },
    {
      "step": "Confirm SIM/eSIM status",
      "how": "Go to Settings > Cellular/Mobile Network. Verify the SIM/eSIM shows as active and not missing or locked. If it looks missing, power off the phone, remove and reinsert the SIM (if physical), then power on.",
      "reason": "A mis-seated or locked SIM prevents the phone from registering on the network."
    },
    {
      "step": "Network mode preference",
      "how": "If you’re on Android: Settings > Network & Internet > Mobile network > Preferred network type, set to 4G/5G (or 4G/3G/2G auto).",
      "reason": "Being stuck on older modes can prevent network attach in some areas."
    },
    {
      "step": "Reboot the phone",
      "how": "Fully power off, wait 20 seconds, then turn it back on.",
      "reason": "Refreshes the radio and clears temporary registration issues."
    }
  ],
  "please_confirm_back": [
    "After the Airplane Mode toggle: did the status bar change or still shows No Service?",
    "What does the SIM/eSIM status show in settings (active, missing, locked)?",
    "Your phone make/model and whether you’re traveling.",
    "The phone number (or other ID) so I can check your line status right away."
  ],
  "next_on_my_side_after_ID": [
    "Look up your account and line status.",
    "Check for any suspensions (e.g., overdue bill or contract-related) or network/roaming settings on the line.",
    "If suspended due to overdue bill, I’ll guide you through payment and resume the line. If not suspended, we’ll continue device-side diagnostics."
  ]
}

