messages.content:
{
  "reassurance": "You didn’t do anything wrong. Your data top-up is active. We just need to make sure your Android is using it correctly for MMS.",
  "thought_process": "MMS must use mobile data even if Wi‑Fi is available. When data was just refueled, Android may need a quick network refresh, correct APN/MMSC settings, and the right app/phone toggles.",
  "keep_wifi_off_for_tests": true,
  "steps": [
    {
      "title": "Quick network refresh",
      "why": "Forces the phone to re-register on the network after the data refuel.",
      "instructions": [
        "Turn Airplane mode ON for 10 seconds, then turn it OFF.",
        "Wait 20–30 seconds until you see 4G/5G bars again."
      ]
    },
    {
      "title": "Confirm mobile data works (simple test)",
      "why": "Verifies the phone can use cellular data (needed for MMS).",
      "instructions": [
        "With Wi‑Fi still OFF, open your browser and go to example.com.",
        "Tell me if the page loads."
      ]
    },
    {
      "title": "Turn OFF Data Saver (if ON)",
      "why": "Data Saver can block background data that MMS needs.",
      "instructions": [
        "Settings > Network & Internet (or Connections) > Data Saver.",
        "If Data Saver is ON, turn it OFF."
      ]
    },
    {
      "title": "Turn OFF Wi‑Fi Calling (temporarily)",
      "why": "Some devices/carriers don’t send MMS over Wi‑Fi Calling reliably.",
      "instructions": [
        "Settings > Network & Internet (or Connections) > Mobile network > Wi‑Fi Calling.",
        "Turn Wi‑Fi Calling OFF."
      ]
    },
    {
      "title": "Make sure no VPN is active",
      "why": "A VPN can block MMS or slow it to a timeout.",
      "instructions": [
        "Settings > Network & Internet > VPN.",
        "If any VPN shows Connected, disconnect it.",
        "Also check the status bar for a key/lock icon; if present, turn the VPN off."
      ]
    },
    {
      "title": "Reset APN to defaults (refreshes MMSC for MMS)",
      "why": "Incorrect APN/MMSC is a very common MMS failure point.",
      "instructions": [
        "Settings > Network & Internet (or Connections) > Mobile network > Access Point Names.",
        "Open the menu (⋮) and tap Reset to default (or choose our carrier APN if it’s listed).",
        "Go back and then restart your phone (power off and back on)."
      ]
    },
    {
      "title": "Check Messages app permissions",
      "why": "MMS needs Storage/Photos & videos and SMS permissions.",
      "instructions": [
        "Settings > Apps > Messages > Permissions.",
        "Allow: Photos and videos (or Storage), and SMS.",
        "Back one screen > Mobile data & Wi‑Fi (or Data usage) > ensure Background data is allowed."
      ]
    }
  ],
  "test": [
    "After Step 1 (Airplane mode refresh), try sending a new picture to your own number.",
    "After the APN reset and reboot (Step 6), try sending a new picture again."
  ],
  "what_to_report_back": [
    "Did example.com load with Wi‑Fi OFF?",
    "After the reboot, did a new picture message send or does it still say Not sent?",
    "If it still fails, any exact error message you see."
  ],
  "note": "Keep Wi‑Fi OFF during these tests so the phone uses mobile data for MMS. Once MMS works, you can turn Wi‑Fi back on."
}

