messages.content:
{
  "reassurance": "You’re doing everything right. Let’s walk through the Messages app permissions and background data step by step on Android. These directly affect MMS.",
  "why_this_matters": "MMS needs permission to access photos/files and send SMS, plus it needs background data allowed to talk to the MMS server.",
  "keep_wifi_off_for_test": true,
  "steps": [
    {
      "title": "Open the Messages app settings",
      "instructions": [
        "Open Settings on your phone.",
        "Tap Apps (or Apps & notifications).",
        "Find and tap Messages. If you see two (Google Messages and Samsung Messages), tap the one you actually use."
      ]
    },
    {
      "title": "Ensure Messages is the default SMS app",
      "why": "Only the default SMS app can send MMS reliably.",
      "instructions": [
        "In Settings > Apps, tap Choose default apps (or Default apps).",
        "Tap SMS app and select Messages (the one you use).",
        "Go back to the Messages app info screen."
      ]
    },
    {
      "title": "Grant required permissions",
      "instructions": [
        "On the Messages app info screen, tap Permissions.",
        "Allow: Photos and videos (or Files and media/Storage) = Allowed.",
        "Allow: SMS = Allowed.",
        "Optional but helpful if present: Notifications = Allowed (not required for sending)."
      ],
      "notes": [
        "If you see Files and media instead of Photos and videos, set it to Allow.",
        "If any of these were not allowed, switch them to Allowed."
      ]
    },
    {
      "title": "Allow background data for Messages",
      "instructions": [
        "Go back one level to the Messages app info screen.",
        "Tap Mobile data & Wi‑Fi (or Data usage).",
        "Turn ON Background data.",
        "If you see Unrestricted data usage or Allow data while Data Saver is on, turn that ON as well."
      ]
    },
    {
      "title": "Test MMS",
      "instructions": [
        "Keep Wi‑Fi OFF and Mobile data ON.",
        "Open Messages and start a new message to a different contact (not yourself).",
        "Attach a small photo or screenshot (<1 MB if possible) and send.",
        "Wait up to 30–60 seconds and tell me what happens."
      ]
    }
  ],
  "what_to_report_back": [
    "Were Photos/Files & media and SMS permissions already allowed, or did you have to enable them?",
    "Was Background data (and Unrestricted data usage) already on, or did you enable it?",
    "After the test send, did the picture go through or is there an error message?"
  ],
  "next_if_needed": "If it still fails after this, we’ll check the APN’s MMSC field together to ensure it’s populated. If it’s blank or incorrect, I’ll escalate to have the correct MMS server provisioned for your line."
}

