    },
    {
      "step": "2",
      "title": "Refresh registration",
      "instructions": "Toggle Airplane Mode ON for ~10 seconds and back OFF."
    },
    {
      "step": "3",
      "title": "Re-check connection",
      "instructions": "After ~30 seconds, run check_network_status and tell me the signal strength (none/poor/fair/good/excellent) and network type (should aim for 4G/5G; 3G is acceptable; avoid 2G)."
    },
    {
      "step": "4",
      "title": "Enable mobile data and test",
      "instructions": "Use toggle_data to turn Mobile Data ON. Turn Wi‑Fi OFF temporarily and try loading any website in your browser. Share whether it loads."
    },
