messages.content:
{
  "message": "Excellent—now that you have strong 5G, the only blocker is that mobile data is OFF. Let’s turn it ON, confirm the internet works over cellular, then test MMS.",
  "thought_process": "MMS needs active mobile data. With 5G signal and account-side roaming already enabled, enabling phone-side mobile data and a quick connectivity check should clear it. If MMS still fails after data works, we’ll check MMS-specific items like APN/MMSC, Wi‑Fi Calling, VPN, and app permissions.",
  "steps_now": [
    {
      "step": "1",
      "title": "Enable Mobile Data",
      "instructions": "Turn mobile data ON (toggle_data). You can also do it via Settings > Network & Internet (or Connections) > Mobile network > Mobile data.",
      "why": "MMS uses mobile data; it won’t send while data is OFF."
    },
    {
      "step": "2",
      "title": "Verify internet over cellular",
      "instructions": "Turn Wi‑Fi OFF temporarily. Open your browser and try loading any website.",
      "what_to_report": "Does the site load over mobile data?",
      "why": "Confirms data is actually working on the cellular network while roaming."
    },
    {
      "step": "3",
      "title": "Test MMS",
      "instructions": "In your messaging app, send a small photo to yourself (aim for under ~500 KB).",
      "what_to_report": "Did it send? If it fails, share any exact error or if it just keeps spinning.",
      "why": "Verifies MMS specifically after confirming data connectivity."
    }
  ],
  "if_internet_does_not_load": [
    {
      "step": "A",
      "title": "Reconfirm Data Roaming and refresh",
      "instructions": "Ensure Data Roaming is ON. If needed, toggle Airplane Mode ON for 10 seconds and back OFF, then retry the website.",
      "why": "Roaming sometimes needs a fresh network registration."
    },
    {
      "step": "B",
      "title": "Data Saver check (Android)",
      "instructions": "Run check_data_restriction_status. If Data Saver is ON, turn it OFF (toggle_data_saver_mode), then retry.",
      "why": "Data Saver can block background data and affect connectivity."
    },
    {
      "step": "C",
      "title": "VPN and Wi‑Fi Calling",
      "instructions": "If a VPN is active, disconnect it. Temporarily turn OFF Wi‑Fi Calling. Retry the website.",
      "why": "Both can sometimes interfere with data while roaming."
    },
    {
      "step": "D",
      "title": "APN reset",
      "instructions": "Run check_apn_settings. If MMSC/APN looks wrong or unknown, reset APN to default (reset_apn_settings), then reboot the phone (reboot_device) and try again.",
      "why": "Incorrect APN can block data and MMS."
    }
  ],
  "if_mms_fails_but_internet_works": [
    {
      "step": "E",
      "title": "Wi‑Fi Calling OFF and VPN OFF",
      "instructions": "Turn OFF Wi‑Fi Calling and disconnect any VPN, then retry sending the MMS.",
      "why": "These can interfere with MMS routing while roaming."
    },
    {
      "step": "F",
      "title": "APN/MMSC verification",
      "instructions": "Run check_apn_settings. If MMSC is missing/incorrect, reset APN (reset_apn_settings), then reboot (reboot_device) and test MMS again.",
      "why": "MMS specifically requires a valid MMSC URL."
    },
    {
      "step": "G",
      "title": "Messaging app permissions (Android)",
      "instructions": "Run check_app_permissions for your messaging app. If Storage/Files or SMS are not granted, grant them (grant_app_permission for storage and sms), then retry MMS.",
      "why": "Without these, the app can’t handle media or send MMS properly."
    }
  ],
  "request": "Please proceed with Steps 1–3 now. Tell me: 1) that mobile data is ON, 2) whether a website loads with Wi‑Fi OFF, and 3) the result of sending a small photo MMS to yourself (including any error if it fails). I’ll guide the next steps immediately based on what you see."
}

