messages.content:
{
  "message": "Thanks for the details—I’ve pulled up your account using 555-123-2002 and confirmed your customer profile is active. I’ll now check the exact line on our side for any suspension or SIM/eSIM issues. In parallel, I’ll guide you through two very safe checks on the phone (Airplane Mode and what the status bar shows). We’ll go slowly, and you can tell me what you see—no need to change anything you’re not comfortable with.",
  "why_these_steps_matter": [
    "Account-side check: If the line is suspended (billing/contract) or the SIM/eSIM is flagged, you’ll get “No Service” no matter what you do on the phone.",
    "Airplane Mode check: If it’s ON, it turns off all cellular radios and instantly causes “No Service.”",
    "Status bar/SIM indicator: Tells us whether the phone sees the SIM (e.g., “No SIM”) versus a network problem (“No Service”). The fix differs based on what we find."
  ],
  "what_i_will_do_next_on_my_side": "Identify which of your lines corresponds to 555-123-2002 and verify its status (active/suspended, roaming setting, recent SIM/eSIM activity). I’ll report back what I find and what that means.",
  "need_from_you": {
    "please_confirm": [
      "Your phone type: iPhone or Android (and model if you know it). This lets me tailor the steps.",
      "Your current city and ZIP (yes, this helps me assess if the issue could be location-specific)."
    ]
  },
  "step_by_step_checks_now": {
    "for_now_do_only_these": [
      {
        "step": "Look at the very top of your screen (status bar). Do you see an airplane icon?",
        "how_to_check": "You don’t need to open settings yet—just glance at the icons. If you see a small airplane, Airplane Mode is ON.",
        "if_yes": "Let me know. I’ll walk you through turning it OFF safely.",
        "why": "Airplane Mode disables all cellular service immediately."
      },
      {
        "step": "Tell me exactly what the signal area says.",
        "how_to_check": "In the same status bar area where bars usually appear, does it say “No Service,” “SOS,” or “No SIM/No SIM card”?",
        "what_to_report": "Please repeat the exact wording you see.",
        "why": "“No SIM” points to a SIM recognition issue; “No Service/SOS” points to a network/line issue."
      }
    ],
    "next_steps_after_you_reply": [
      "If Airplane Mode is ON, I’ll guide you to switch it OFF (one-tap instruction for iPhone/Android).",
      "If it shows “No SIM,” I’ll guide you through a simple, careful SIM check (power off, reinsert) only if you’re comfortable.",
      "If it shows “No Service/SOS,” we’ll do a quick safe setting toggle and a reboot, and I’ll correlate with what I find on your line."
    ]
  },
  "reassurance": "We’ll take this one step at a time. Please tell me your phone type, your city/ZIP, whether you see an airplane icon, and the exact status text shown where the signal bars usually are. While you do that, I’m preparing to check your line status on our side."
}

