      "how": [
        "Settings > Network & Internet > Data Saver > OFF."
      ],
      "why": "Data Saver can restrict MMS background transfers."
    },
    {
      "step": "Disable any VPN",
      "how": [
        "If you use a VPN app, disconnect/turn it OFF."
      ],
      "why": "VPNs can break MMS routing while roaming."
    },
