messages.content:
{
  "message": "Thanks for going through those steps. Since refuel + APN reset + reboot didn’t restore mobile data, we’ll refresh your network registration and verify the SIM and radio state next.",
  "thought_process": "Your account and line are active, and we’ve added 2 GB. That means the network should allow data. When data still won’t flow, the common remaining causes are: (1) the phone is not registering correctly to the network (airplane-mode refresh helps), (2) SIM recognition issues (reseat/check SIM status), (3) radio mode conflicts (try 4G-only), or (4) a rare provisioning issue we must handle on our side. We’ll try all device-side fixes before escalating.",
  "steps": [
    {
      "title": "Read the status bar",
      "why": "Confirms whether the phone shows network registration.",
      "do_this": [
        "With Wi‑Fi OFF, look at the top status bar and tell me:",
        "- Signal bars: none/1/2/3/4?",
        "- Network type indicator: 5G/4G/LTE/3G/2G or nothing?",
        "- Any airplane icon showing?"
      ]
    },
    {
      "title": "Airplane mode refresh",
      "why": "Forces a full re-registration to the network.",
      "do_this": [
        "Turn ON Airplane mode and leave it ON for 30–60 seconds.",
        "Turn Airplane mode OFF.",
        "Wait 30 seconds, then try loading example.com again (Wi‑Fi still OFF)."
      ]
    },
    {
      "title": "Turn OFF Wi‑Fi Calling (if available)",
      "why": "Sometimes interferes with MMS/data handoff.",
      "do_this": [
        "Settings > Network/Connections > Wi‑Fi Calling: turn it OFF.",
        "Try loading example.com again."
      ]
    },
    {
      "title": "Check SIM status",
      "why": "Verifies whether the phone sees the SIM correctly.",
      "do_this": [
        "Settings > About phone > SIM status (or Status > SIM status).",
        "Tell me what it shows: Active/Connected, Missing, or Locked?"
      ],
      "actions_based_on_result": [
        "If Missing: Power off the phone, remove and reinsert the SIM (or if you use eSIM, toggle the mobile line OFF then back ON), then power on and test example.com.",
        "If Locked: Do not guess PIN/PUK. Tell me, and I’ll transfer you to a human agent for SIM security assistance.",
        "If Active: Proceed to the next step."
      ]
    },
    {
      "title": "Set network to 4G/LTE only (temporarily)",
      "why": "Eliminates 5G-specific registration issues.",
      "do_this": [
        "Settings > Mobile network > Preferred network type.",
        "Choose 4G/LTE only (or ‘LTE only’ if available).",
        "Wait 20–30 seconds and test example.com again."
      ]
    },
    {
      "title": "Optional: Reseat SIM proactively",
      "why": "Resets the SIM’s connection to the phone hardware.",
      "do_this": [
        "Power the phone off completely.",
        "If physical SIM: eject the SIM tray, reinsert the SIM snugly.",
        "If eSIM: in Settings > Mobile network, toggle your eSIM line OFF and then ON.",
        "Power back on and test example.com."
      ]
    }
  ],
  "what_to_report_back": [
    "Status bar details: signal bars and network type indicator.",
    "After airplane mode refresh: does example.com load?",
    "Is Wi‑Fi Calling OFF now?",
    "SIM status result (Active/Missing/Locked).",
    "After setting 4G/LTE only: can you load example.com?",
    "If you reseated the SIM: did data start working afterward?"
  ],
  "next_step_note": "If mobile data still won’t come up after these steps, it may be a backend provisioning issue. I’ll summarize everything we tried and transfer you to a human agent to run a network re-provision on your line."
}

