messages.content:
{
  "acknowledgement": "Thanks for the detailed update. Your mobile data is excellent now, so MMS is likely being blocked by a phone configuration issue (Wi‑Fi Calling, APN/MMSC, app permissions, Data Saver, or VPN). I’ll walk you through quick checks in order.",
  "why_these_steps": "MMS relies on the MMSC server in your APN, requires the messaging app to have Storage and SMS permissions, and can be affected by Wi‑Fi Calling, Data Saver, or a VPN—especially while roaming.",
  "keep_wifi_off_for_tests": true,
  "steps_in_order": [
    {
      "step": 1,
      "action": "check_wifi_calling_status",
      "instructions": "If it says Wi‑Fi Calling is ON, run toggle_wifi_calling to turn it OFF. Then try sending a small MMS again.",
      "why": "Wi‑Fi Calling can sometimes interfere with MMS, particularly while roaming."
    },
    {
      "step": 2,
      "action": "check_apn_settings",
      "instructions": "Look at the result and tell me the APN name and whether an MMSC URL is shown. If the MMSC is missing/blank, run reset_apn_settings, then reboot_device. After reboot, ensure Mobile Data and Data Roaming are ON, wait ~20 seconds for 4G/5G to appear, and test MMS again.",
      "why": "A missing/incorrect MMSC URL prevents MMS from sending/receiving."
    },
    {
      "step": 3,
      "action": "check_app_permissions",
      "parameters": { "app_name": "messaging" },
      "instructions": "Confirm the messaging app has both storage and sms permissions. If either is missing, run grant_app_permission for the missing ones (storage and/or sms). Then try sending an MMS again.",
      "why": "The app needs access to local media (storage) and SMS/MMS functions."
    },
    {
      "step": 4,
      "action": "check_data_restriction_status",
      "instructions": "If Data Saver is ON, run toggle_data_saver_mode to turn it OFF. Then retry MMS.",
      "why": "Data Saver can restrict background data paths that MMS relies on."
    },
    {
      "step": 5,
      "action": "check_vpn_status",
      "instructions": "If a VPN is connected, run disconnect_vpn. Then retry MMS.",
      "why": "Some VPNs can block/alter MMS traffic."
    },
    {
      "step": 6,
      "action": "can_send_mms",
      "instructions": "Run can_send_mms. Share what it reports. If MMS still fails after all above steps—even if MMSC was present—run reset_apn_settings anyway, then reboot_device, re-enable Mobile Data + Data Roaming, wait for 4G/5G, and test again.",
      "why": "This provides a definitive capability check, and resetting APN can resolve subtle misconfigurations."
    }
  ],
  "what_to_report_back": [
    "Wi‑Fi Calling status (ON/OFF) and whether turning it OFF changed anything.",
    "APN name and whether MMSC URL is present (and its value, if shown).",
    "Messaging app permissions status for storage and sms before/after.",
    "Whether Data Saver or a VPN was ON.",
    "Result of can_send_mms, and whether an MMS sends after these changes."
  ]
}

