  "thought_process": "Mobile data is working great, so MMS is likely being blocked by either Wi‑Fi Calling interactions, APN/MMSC configuration, or app-level restrictions. We’ll rule those out in order of most common and quickest to fix.",
  "next_steps_in_order": [
    {
      "step": "Turn OFF Wi‑Fi Calling temporarily",
      "how": "Settings > Connections (or Network & Internet) > Wi‑Fi Calling > toggle OFF",
      "why": "Some networks don’t support MMS over Wi‑Fi Calling while roaming. Disabling it forces MMS over mobile data.",
      "then_try": "With Wi‑Fi still OFF, try sending a small photo MMS."
    },
    {
      "step": "Verify/Reset APN so MMSC is correct",
      "how": [
        "Settings > Network & Internet (or Connections) > Mobile network > Access Point Names.",
        "Tap your carrier APN to view details and look for an entry named MMSC (a URL). If you’re unsure or it’s blank:",
        "Tap the three‑dot menu > Reset to default.",
        "Reboot the phone after resetting APN."
      ],
      "why": "A missing/incorrect MMSC is a very common cause of MMS failure.",
      "then_try": "After the reboot, keep Wi‑Fi OFF and try sending the MMS again."
    },
    {
      "step": "Confirm the Messages app has required permissions",
      "how": "Settings > Apps > Messages (your default app) > Permissions > ensure Storage/Photos and SMS are allowed. Also in App info > Mobile data & Wi‑Fi, make sure ‘Allow background data usage’ is ON.",
      "why": "Without storage/SMS permissions or with background data restricted, MMS can fail.",
      "then_try": "Retry sending the MMS with Wi‑Fi OFF."
    },
    {
      "step": "Ensure no VPN is active",
      "how": "Settings > Network & Internet > VPN > if connected, disconnect the VPN temporarily.",
      "why": "Some VPNs can interfere with MMS routing.",
      "then_try": "Retry the MMS."
    },
    {
      "step": "Make sure Data Saver is OFF",
      "how": "Settings > Network & Internet > Data Saver > toggle OFF.",
      "why": "Data Saver can block background transfers used by MMS.",
      "then_try": "Retry the MMS."
    }
  ],
  "quick_test_after_each_step": "After each step, keep Wi‑Fi OFF and send a small photo MMS to test.",
  "if_still_failing_after_all_steps": [
    "Tell me exactly which steps you completed and what happened.",
    "Also share any updated error text in the messaging app."
  ],
  "questions": [
    "Please start with turning OFF Wi‑Fi Calling and retry the MMS. Did it send?",
    "If not, proceed to the APN reset + reboot and let me know the result."
  ]
}

messages.content:
{
  "thought_process": "Since mobile data works great and Wi‑Fi Calling is OFF, the most likely blocker is incorrect or stale APN/MMSC settings for MMS. Resetting APN to default and rebooting typically fixes this. If not, we’ll verify the Messages app permissions and data restrictions.",
  "next_step_primary": {
    "title": "Reset APN to default, then reboot",
    "why": "MMS depends on the MMSC entry in your APN. If it’s missing/incorrect, MMS fails even when data works.",
    "steps": [
      "Settings > Network & Internet (or Connections) > Mobile network > Access Point Names.",
      "Tap the three‑dot menu (⋮) > Reset to default.",
      "Restart (reboot) the phone."
    ]
  },
  "after_reboot_test": [
    "Turn Wi‑Fi OFF.",
    "Ensure Mobile data and Data roaming are ON.",
    "Wait ~20–30 seconds, then load a simple webpage (just to confirm data still works).",
    "With Wi‑Fi still OFF, try sending a small photo MMS."
  ],
  "if_still_not_working": {
    "title": "App permissions and data restrictions",
    "steps": [
      "Messages app permissions: Settings > Apps > Messages (default) > Permissions > allow Photos/Media (or Storage) and SMS.",
      "Background data: In the Messages app info > Mobile data & Wi‑Fi > ensure ‘Allow background data usage’ is ON (and if available, ‘Unrestricted data’ ON).",
      "VPN: Settings > Network & Internet > VPN > if connected, disconnect temporarily and retry.",
      "Data Saver: Settings > Network & Internet > Data Saver > turn OFF."
    ],
    "then_try": "Keep Wi‑Fi OFF and retry sending the MMS."
  },
  "questions": [
    "Please go ahead with the APN reset + reboot first. After you try sending the MMS again, did it go through?",
    "If it still fails, which of the permission/data restriction checks did you complete, and what happened when you retried?"
  ]
}

