messages.content:
{
  "thought_process": "Yes—if the Messages app can’t access your photos/media, MMS can fail even when mobile data works. Let’s grant the app’s Photos/Storage permission and retest. If the permission isn’t visible under the app, use Android’s Permission Manager to set it.",
  "why_this_matters": "MMS needs the app to read the photo/video file so it can package and send it over mobile data.",
  "steps_to_grant_permission": [
    {
      "option": "From the Messages app permissions screen",
      "how": [
        "Settings > Apps > Messages (your default app) > Permissions.",
        "Look for an entry named Photos and videos or Files and media (varies by Android version).",
        "Set it to Allow."
      ]
    },
    {
      "option": "Via Permission Manager (if you don’t see it in the app list)",
      "how": [
        "Settings > Privacy > Permission manager.",
        "Tap Photos and videos (or Files and media).",
        "Find Messages and set it to Allow (Allow all or Allow selected photos/videos is fine)."
      ]
    },
    {
      "tip": "Trigger the permission prompt",
      "how": [
        "Open Messages, start a new message, tap the attachment/clip icon, choose Gallery/Photos, and pick a small photo.",
        "If prompted for access to photos/media, tap Allow."
      ]
    }
  ],
  "then_test": [
    "Keep Wi‑Fi OFF; ensure Mobile data and Data roaming are ON.",
    "Wait ~10–20 seconds.",
    "Send a small photo MMS (try a simple JPEG)."
  ],
  "if_still_not_working_after_permission": [
    "Tell me exactly what you see (any error text).",
    "We’ve completed all standard device and network checks (roaming enabled, data active/refueled, APN reset, Wi‑Fi Calling OFF, permissions verified). If it still fails, I will escalate to a human agent for deeper MMS routing diagnostics."
  ],
  "questions": [
    "Were you able to set Photos/Media (Storage) permission for Messages to Allow?",
    "After granting it and retrying with Wi‑Fi OFF, did the MMS send successfully?"
  ]
}

