  "status": "Good progress — your SIM is now active with 5G and data enabled.",
  "goal": "Fix MMS-specific causes now that service and data are up.",
  "why": "MMS depends on mobile data plus a correct MMSC (in APN). While roaming, Wi‑Fi Calling, VPN, or Data Saver can also interfere.",
  "steps": [
    {
      "id": 1,
      "action": "Confirm mobile data works",
      "how": "With Wi‑Fi OFF, open any web page (e.g., example.com).",
      "reason": "Verifies general data connectivity required for MMS."
    },
    {
      "id": 2,
      "action": "Turn Wi‑Fi Calling OFF (temporarily)",
      "how": "Run check_wifi_calling_status. If it says ON, run toggle_wifi_calling to turn it OFF.",
      "reason": "MMS may not work over Wi‑Fi Calling while roaming."
    },
    {
      "id": 3,
      "action": "Check VPN and disconnect if active",
      "how": "Run check_vpn_status. If connected, run disconnect_vpn.",
      "reason": "Some VPNs break MMS routing."
    },
    {
      "id": 4,
      "action": "Turn Data Saver OFF (if ON)",
      "how": "Run check_data_restriction_status. If Data Saver is ON, run toggle_data_saver_mode to turn it OFF.",
      "reason": "Data Saver can interfere with MMS transfers."
    },
    {
      "id": 5,
      "action": "Verify APN/MMSC settings",
      "how": "Run check_apn_settings and tell me the APN name and the MMSC URL. If MMSC is blank/missing or looks incorrect, run reset_apn_settings and then run reboot_device.",
      "reason": "A correct MMSC URL is required for MMS."
    },
    {
      "id": 6,
      "action": "Confirm messaging app permissions",
      "how": "Run check_app_permissions(app_name=\"messaging\"). If storage or sms are not granted, run grant_app_permission for each missing one.",
      "reason": "The app needs storage and SMS permissions to send MMS."
    },
    {
      "id": 7,
      "action": "Retest MMS",
      "how": "Keep Wi‑Fi OFF for the test. Send a small photo to yourself.",
      "reason": "Validates that MMS works over mobile data after the adjustments."
    }
  ],
  "please_report_back": [
    "1) Did the web page load?",
    "2) Wi‑Fi Calling status now (ON/OFF)?",
    "3) VPN active (Yes/No)?",
    "4) Data Saver (ON/OFF)?",
    "5) APN name and MMSC URL values?",
    "6) Messaging app permissions currently granted?"
  ],
  "note": "If APN is reset, please reboot before testing MMS. If everything above checks out and MMS still fails, we’ll take the next diagnostic step."
}

