{
  "thought_process": "Your phone says the SIM is missing. That would definitely cause ‘No Signal’ and stop MMS and data. The most likely fix is to reseat the SIM so the phone can detect it again. We’ll go one simple step at a time.",
  "step_1": {
    "title": "Power the phone OFF",
    "why": "It’s safest to handle the SIM while the phone is off.",
    "how": [
      "Hold the power button (and volume button on some phones) and slide or tap to power off.",
      "Wait until the screen is fully black."
    ],
    "please_reply_when_done": "Say 'Off' when it’s powered down."
  },
  "step_2": {
    "title": "Locate and reseat the SIM",
    "pre_check": "Do you see a tiny pinhole next to a slim tray on the side or top edge of the phone? That’s the SIM tray.",
    "if_tray_is_present": [
      "Use the SIM eject tool (or a small paperclip) and press gently into the pinhole until the tray pops out.",
      "Remove the tray and the SIM card. Note the SIM’s orientation (angled corner).",
      "Inspect the SIM and tray for dust/debris; gently wipe if needed.",
      "Place the SIM back in the tray in the same orientation, with contacts flat in the tray.",
      "Slide the tray back in firmly until it sits flush."
    ],
    "if_no_tray_found": [
      "Some phones use eSIM (no physical tray). If you don’t see any tray, tell me the phone brand/model (e.g., Apple iPhone 14, Samsung Galaxy S22, Google Pixel 7), and I’ll guide eSIM checks."
    ],
    "safety_tip": "Be careful not to insert the tool into a microphone hole—look specifically for a tiny pinhole next to a thin tray outline."
  },
  "step_3": {
    "title": "Power ON and wait for network",
    "how": [
      "Turn the phone back ON.",
      "Wait up to 90 seconds. Watch the top of the screen for signal bars and a network label (4G/LTE/5G). In France you may also see an ‘R’ for roaming."
    ],
    "what_to_report": "Tell me exactly what you see: signal bars? 4G/LTE/5G? or still ‘No SIM’/‘No Service’?"
  },
  "next_if_success": [
    "If bars appear: we’ll make sure Mobile Data and Data Roaming are ON and then try sending your picture message again."
  ],
  "next_if_issue_persists": [
